(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('low');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.env.setTime(11);
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    __rhf.god(true);
    const ids = ['btn-wardrobe', 'btn-map', 'btn-journal', 'btn-pause', 'bite-pill', 'hud-time', 'compass', 'objective', 'minimap'];
    const r = ids.map((id) => {
      const b = document.getElementById(id).getBoundingClientRect();
      return id + ' ' + Math.round(b.left) + ',' + Math.round(b.top) + ' ' + Math.round(b.width) + 'x' + Math.round(b.height);
    });
    return r.join(' | ');
  })()

(() => {
    const g = __rhf.game;
    return 'open: ' + g.screens.current + ', options ' + document.querySelectorAll('.look-opt').length + ', money ' + g.state.money;
  })()

(() => {
    const s = __rhf.game.state;
    return 'after the Hawaiian shirt: wearing ' + s.look.shirt + ', owned ' + JSON.stringify(s.wardrobe) + ', money ' + s.money;
  })()

(() => {
    const s = __rhf.game.state;
    return 'antler hat with ' + s.money + ' left: hat ' + s.look.hat + ', toast ' + [...document.querySelectorAll('#toasts > *')].map((e) => e.textContent).pop();
  })()

(() => {
    const s = __rhf.game.state;
    return 'look ' + JSON.stringify(s.look) + ', owned ' + JSON.stringify(s.wardrobe) + ', money ' + s.money;
  })()

(() => {
    const g = __rhf.game;
    g.screens.close();
    // the sleeve colours in the hand model: the Hawaiian teal must be there
    const col = g.viewmodel.rodHand.geometry.attributes.color;
    // vertex colours are linear: teal is almost no red, strong green and blue
    let teal = 0;
    for (let i = 0; i < col.count; i++) if (col.getX(i) < 0.05 && col.getY(i) > 0.3 && col.getZ(i) > 0.35) teal++;
    // the save keeps the look
    g.save && g.save();
    const raw = localStorage.getItem('rubenHotrodFishing.save.v1');
    const d = raw ? JSON.parse(raw) : {};
    return 'teal vertices on the sleeve ' + teal + ' of ' + col.count + '; saved look ' + JSON.stringify(d.look) + ', saved wardrobe ' + JSON.stringify(d.wardrobe);
  })()

(() => {
    const g = __rhf.game;
    __rhf.session.enterCar();
    g.hotrod.camMode = 'chase';
    return 'in the car, driver shown ' + g.hotrod.driver.visible;
  })()

(() => {
    const g = __rhf.game;
    // swing the chase cam round to the side for a look at Ruben
    g.hotrod.camYaw = 1.9;
    return 'cam yaw ' + g.hotrod.camYaw;
  })()

(() => {
